:root {
  --bg: #1b1f2a;
  --bg-accent: #232838;
  --card: #f7f5f0;
  --ink: #1b1f2a;
  --ink-soft: #4a4f5e;
  --accent: #e4572e;
  --accent-dark: #c23f1c;
  --focus: #2e6ff2;
  --border: #d9d4c7;
  --swatch-border: rgba(0, 0, 0, 0.14);
  --radius: 14px;
  --shadow: 0 18px 40px rgba(0, 0, 0, 0.35);
  font-size: 16px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  color: var(--ink);
  background: radial-gradient(circle at 20% 0%, var(--bg-accent), var(--bg) 60%);
}

.app {
  width: 100%;
  max-width: 680px;
  background: var(--card);
  border-radius: calc(var(--radius) + 6px);
  box-shadow: var(--shadow);
  padding: 28px 24px 32px;
}

.app__header {
  text-align: center;
  margin-bottom: 24px;
}

.app__title {
  margin: 0 0 6px;
  font-size: 1.75rem;
  letter-spacing: 0.01em;
}

.app__subtitle {
  margin: 0;
  color: var(--ink-soft);
  font-size: 1rem;
}

.swatches {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.swatch {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.swatch__color {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 140px;
  border-radius: var(--radius);
  border: 2px solid var(--swatch-border);
  box-shadow: inset 0 -42px 42px -30px rgba(0, 0, 0, 0.5);
  transition: transform 120ms ease, box-shadow 120ms ease;
}

.swatch__color:hover {
  transform: translateY(-2px);
  box-shadow: inset 0 -42px 42px -30px rgba(0, 0, 0, 0.5), 0 6px 14px rgba(0, 0, 0, 0.18);
}

.swatch__hex {
  display: block;
  width: 100%;
  padding: 6px 4px;
  text-align: center;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #fff;
  background: rgba(0, 0, 0, 0.42);
  border-radius: 0 0 calc(var(--radius) - 2px) calc(var(--radius) - 2px);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
}

.swatch__lock {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 40px;
  padding: 8px 6px;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink);
  background: #fff;
  border: 2px solid var(--border);
  border-radius: 10px;
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease, transform 80ms ease;
}

.swatch__lock:hover {
  background: #f0ece2;
  border-color: var(--ink-soft);
}

.swatch__lock:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.swatch__lock:active {
  transform: scale(0.97);
}

.swatch__lock[aria-pressed="true"] {
  color: #fff;
  background: var(--ink);
  border-color: var(--ink);
}

.swatch__lock[aria-pressed="true"]:hover {
  background: #2c3242;
}

.swatch__lock-icon {
  font-size: 1rem;
  line-height: 1;
}

.actions {
  margin-top: 26px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.btn {
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  border-radius: 999px;
  transition: background 120ms ease, transform 80ms ease, box-shadow 120ms ease;
}

.btn--generate {
  width: 100%;
  max-width: 320px;
  min-height: 52px;
  padding: 12px 28px;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  color: #fff;
  background: var(--accent);
  border: 2px solid var(--accent);
  box-shadow: 0 6px 16px rgba(228, 87, 46, 0.35);
}

.btn--generate:hover {
  background: var(--accent-dark);
  border-color: var(--accent-dark);
}

.btn--generate:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn--generate:active {
  transform: translateY(1px) scale(0.99);
  box-shadow: 0 3px 8px rgba(228, 87, 46, 0.35);
}

.hint {
  margin: 0;
  min-height: 1.5em;
  text-align: center;
  color: var(--ink-soft);
  font-size: 0.95rem;
}

@media (max-width: 560px) {
  .swatches {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .swatch:last-child {
    grid-column: span 1;
  }
}

@media (max-width: 380px) {
  body {
    padding: 12px 8px;
  }

  .app {
    padding: 20px 14px 24px;
  }

  .swatches {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .swatch:last-child {
    grid-column: span 2;
  }

  .swatch__color {
    min-height: 110px;
  }

  .swatch__hex {
    font-size: 0.85rem;
  }
}

(function () {
  "use strict";

  var SWATCH_COUNT = 5;

  var swatchesEl = document.getElementById("swatches");
  var template = document.getElementById("swatch-template");
  var generateBtn = document.getElementById("generate");
  var hintEl = document.getElementById("hint");

  var state = {
    colors: [],
    locked: []
  };

  function hslToHex(h, s, l) {
    var hh = ((h % 360) + 360) % 360;
    var ss = Math.max(0, Math.min(100, s)) / 100;
    var ll = Math.max(0, Math.min(100, l)) / 100;

    var c = (1 - Math.abs(2 * ll - 1)) * ss;
    var x = c * (1 - Math.abs(((hh / 60) % 2) - 1));
    var m = ll - c / 2;
    var r = 0, g = 0, b = 0;

    if (hh < 60) { r = c; g = x; b = 0; }
    else if (hh < 120) { r = x; g = c; b = 0; }
    else if (hh < 180) { r = 0; g = c; b = x; }
    else if (hh < 240) { r = 0; g = x; b = c; }
    else if (hh < 300) { r = x; g = 0; b = c; }
    else { r = c; g = 0; b = x; }

    function toHex(v) {
      var n = Math.round((v + m) * 255);
      n = Math.max(0, Math.min(255, n));
      return n.toString(16).padStart(2, "0");
    }

    return "#" + toHex(r) + toHex(g) + toHex(b);
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generatePalette() {
    var baseHue = randomInt(0, 359);
    var scheme = randomInt(0, 2);
    var offsets;

    if (scheme === 0) {
      offsets = [0, 32, 64, 96, 128];
    } else if (scheme === 1) {
      offsets = [0, 40, 160, 200, 320];
    } else {
      offsets = [0, 24, 48, 72, 96];
    }

    var saturation = randomInt(58, 78);
    var lightnessBase = randomInt(46, 58);
    var colors = [];

    for (var i = 0; i < SWATCH_COUNT; i++) {
      var hue = baseHue + offsets[i] + randomInt(-6, 6);
      var sat = saturation + randomInt(-8, 8);
      var light = lightnessBase + (i - 2) * 7 + randomInt(-4, 4);
      colors.push(hslToHex(hue, sat, light));
    }

    return colors;
  }

  function render() {
    swatchesEl.innerHTML = "";

    state.colors.forEach(function (hex, i) {
      var node = template.content.firstElementChild.cloneNode(true);
      var colorEl = node.querySelector(".swatch__color");
      var hexEl = node.querySelector(".swatch__hex");
      var lockBtn = node.querySelector(".swatch__lock");
      var iconEl = node.querySelector(".swatch__lock-icon");
      var labelEl = node.querySelector(".swatch__lock-label");

      colorEl.style.backgroundColor = hex;
      colorEl.setAttribute("aria-label", "Color swatch " + (i + 1) + ": " + hex);
      hexEl.textContent = hex;

      var isLocked = state.locked[i];
      lockBtn.setAttribute("aria-pressed", isLocked ? "true" : "false");
      lockBtn.setAttribute("aria-label", (isLocked ? "Unlock" : "Lock") + " color " + hex);
      iconEl.textContent = isLocked ? "🔒" : "🔓";
      labelEl.textContent = isLocked ? "Locked" : "Lock";

      lockBtn.addEventListener("click", function () {
        state.locked[i] = !state.locked[i];
        render();
        updateHint();
      });

      swatchesEl.appendChild(node);
    });
  }

  function updateHint() {
    var lockedCount = state.locked.filter(Boolean).length;
    if (lockedCount === SWATCH_COUNT) {
      hintEl.textContent = "All colors are locked. Unlock one to generate new colors.";
    } else if (lockedCount > 0) {
      hintEl.textContent = lockedCount + " color" + (lockedCount === 1 ? "" : "s") + " locked. Press Generate to refresh the rest.";
    } else {
      hintEl.textContent = "Press Generate for a new harmonious palette.";
    }
  }

  function generate() {
    var fresh = generatePalette();
    var next = state.colors.slice();

    for (var i = 0; i < SWATCH_COUNT; i++) {
      if (!state.locked[i]) {
        next[i] = fresh[i];
      }
    }

    state.colors = next;
    render();
    updateHint();
  }

  function init() {
    state.colors = generatePalette();
    state.locked = new Array(SWATCH_COUNT).fill(false);
    render();
    updateHint();

    generateBtn.addEventListener("click", generate);
  }

  init();
})();
